BEGIN;
CREATE SCHEMA IF NOT EXISTS dunna_private;
REVOKE ALL ON SCHEMA dunna_private FROM PUBLIC, anon, authenticated;
SET LOCAL search_path TO dunna_private,pg_catalog;
CREATE TABLE IF NOT EXISTS stores(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL,city TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,active BIGINT NOT NULL DEFAULT 1,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,store_id TEXT,user_id TEXT,action TEXT NOT NULL,entity_id TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS renave_preparation(store_id TEXT PRIMARY KEY REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deals(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchases(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consignments(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),data TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicle_engagement(store_id TEXT NOT NULL REFERENCES stores(id),vehicle_id TEXT NOT NULL REFERENCES vehicles(id),view_id TEXT NOT NULL,source TEXT NOT NULL,viewed BIGINT NOT NULL,elapsed_ms BIGINT NOT NULL DEFAULT 0,interested BIGINT NOT NULL DEFAULT 0,created BIGINT NOT NULL,PRIMARY KEY(store_id,vehicle_id,view_id,source));
CREATE TABLE IF NOT EXISTS analytics_activation(store_id TEXT PRIMARY KEY REFERENCES stores(id),started BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS vehicles_store ON vehicles(store_id);
CREATE INDEX IF NOT EXISTS leads_store ON leads(store_id);
CREATE INDEX IF NOT EXISTS people_store ON people(store_id);
CREATE INDEX IF NOT EXISTS deals_store ON deals(store_id);
CREATE INDEX IF NOT EXISTS ledger_store ON ledger(store_id);
CREATE INDEX IF NOT EXISTS purchases_store ON purchases(store_id);
CREATE UNIQUE INDEX IF NOT EXISTS purchases_active_vehicle ON purchases(store_id,(data::jsonb->>'vehicleId')) WHERE (data::jsonb->>'status')='confirmed';
CREATE INDEX IF NOT EXISTS consignments_store ON consignments(store_id);
CREATE UNIQUE INDEX IF NOT EXISTS consignment_vehicle ON consignments(store_id,(data::jsonb->>'vehicleId')) WHERE (data::jsonb->>'status') IN ('active','sold');
CREATE INDEX IF NOT EXISTS engagement_period ON vehicle_engagement(store_id,created);
CREATE TABLE IF NOT EXISTS migration_log(id text PRIMARY KEY,completed_at timestamptz DEFAULT now());
CREATE OR REPLACE FUNCTION public.dunna_import_initial_data(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=dunna_private,pg_catalog AS $$
BEGIN
PERFORM pg_advisory_xact_lock(6748021001);
IF EXISTS(SELECT 1 FROM migration_log WHERE id='local-20261027') THEN RAISE EXCEPTION 'Import already completed'; END IF;
IF EXISTS(SELECT 1 FROM users) THEN RAISE EXCEPTION 'Destination already contains users'; END IF;
INSERT INTO stores SELECT * FROM json_populate_recordset(NULL::stores,(payload->'stores')::json) ON CONFLICT DO NOTHING;
INSERT INTO users SELECT * FROM json_populate_recordset(NULL::users,(payload->'users')::json) ON CONFLICT DO NOTHING;
INSERT INTO vehicles SELECT * FROM json_populate_recordset(NULL::vehicles,(payload->'vehicles')::json) ON CONFLICT DO NOTHING;
INSERT INTO leads SELECT * FROM json_populate_recordset(NULL::leads,(payload->'leads')::json) ON CONFLICT DO NOTHING;
INSERT INTO audit SELECT * FROM json_populate_recordset(NULL::audit,(payload->'audit')::json) ON CONFLICT DO NOTHING;
INSERT INTO renave_preparation SELECT * FROM json_populate_recordset(NULL::renave_preparation,(payload->'renave_preparation')::json) ON CONFLICT DO NOTHING;
INSERT INTO people SELECT * FROM json_populate_recordset(NULL::people,(payload->'people')::json) ON CONFLICT DO NOTHING;
INSERT INTO deals SELECT * FROM json_populate_recordset(NULL::deals,(payload->'deals')::json) ON CONFLICT DO NOTHING;
INSERT INTO ledger SELECT * FROM json_populate_recordset(NULL::ledger,(payload->'ledger')::json) ON CONFLICT DO NOTHING;
INSERT INTO purchases SELECT * FROM json_populate_recordset(NULL::purchases,(payload->'purchases')::json) ON CONFLICT DO NOTHING;
INSERT INTO consignments SELECT * FROM json_populate_recordset(NULL::consignments,(payload->'consignments')::json) ON CONFLICT DO NOTHING;
INSERT INTO vehicle_engagement SELECT * FROM json_populate_recordset(NULL::vehicle_engagement,(payload->'vehicle_engagement')::json) ON CONFLICT DO NOTHING;
INSERT INTO analytics_activation SELECT * FROM json_populate_recordset(NULL::analytics_activation,(payload->'analytics_activation')::json) ON CONFLICT DO NOTHING;
PERFORM setval(pg_get_serial_sequence('dunna_private.audit','id'),GREATEST(COALESCE((SELECT MAX(id) FROM audit),0),1));
INSERT INTO migration_log(id) VALUES('local-20261027');
END;$$;
REVOKE ALL ON FUNCTION public.dunna_import_initial_data(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.dunna_import_initial_data(jsonb) TO service_role;
COMMIT;
NOTIFY pgrst,'reload schema';
